const CATS=[{name:"JDM",fa:"fas fa-sun",desc:"Japanese domestic market legends",color:"#e8392a",badge:"badge-jdm"},{name:"Euro",fa:"fas fa-compass",desc:"Precision engineering from Europe",color:"#3b82f6",badge:"badge-euro"},{name:"Muscle",fa:"fas fa-bolt",desc:"American horsepower and raw power",color:"#f0a030",badge:"badge-muscle"},{name:"Sports Car",fa:"fas fa-car",desc:"High-performance sports machines",color:"#a855f7",badge:"badge-sports"},{name:"GT",fa:"fas fa-road",desc:"Grand tourers built for distance and speed",color:"#6366f1",badge:"badge-gt"},{name:"Supercar",fa:"fas fa-rocket",desc:"Exotic and ultra-high-performance machines",color:"#fb923c",badge:"badge-supercar"},{name:"Hypercar",fa:"fas fa-rocket",desc:"Hypercars, ultra-exotics, and track weapons",color:"#ec4899",badge:"badge-hypercar"},{name:"Classic",fa:"fas fa-star",desc:"Timeless machines from golden eras",color:"#c9a84c",badge:"badge-classic"},{name:"Vintage",fa:"fas fa-history",desc:"Pre-1970s icons and veteran automobiles",color:"#b45309",badge:"badge-vintage"},{name:"Retro",fa:"fas fa-clock",desc:"Nostalgic builds and era-inspired machines",color:"#d97706",badge:"badge-retro"},{name:"Cult Classic",fa:"fas fa-certificate",desc:"Niche legends with passionate followings",color:"#7c3aed",badge:"badge-cult"},{name:"Hatch",fa:"fas fa-car-side",desc:"Hot hatches and compact performance builds",color:"#10b981",badge:"badge-hatch"},{name:"Tuner",fa:"fas fa-wrench",desc:"Modified and tuned street machines",color:"#f43f5e",badge:"badge-tuner"},{name:"Luxury",fa:"fas fa-gem",desc:"Premium and prestige automobiles",color:"#14b8a6",badge:"badge-luxury"},{name:"Saloon",fa:"fas fa-car",desc:"Sedan and saloon performance builds",color:"#64748b",badge:"badge-saloon"},{name:"SUV",fa:"fas fa-car-side",desc:"Sport utility builds, lifted and tuned",color:"#0ea5e9",badge:"badge-suv"},{name:"Truck",fa:"fas fa-truck-pickup",desc:"Full-size haulers and performance pickups",color:"#78716c",badge:"badge-truck"},{name:"Utility",fa:"fas fa-tools",desc:"Work vehicles, vans, and utility builds",color:"#854d0e",badge:"badge-utility"},{name:"Electric",fa:"fas fa-plug",desc:"EV builds, conversions, and electric tuners",color:"#4ade80",badge:"badge-electric"},{name:"Off-Road",fa:"fas fa-mountain",desc:"Built for the dirt, mud, and trails",color:"#22c55e",badge:"badge-offroad"},{name:"Rally",fa:"fas fa-map-signs",desc:"Stage rally and special stage machines",color:"#eab308",badge:"badge-rally"},{name:"Drift",fa:"fas fa-wind",desc:"Angle seekers and sideways specialists",color:"#f43f5e",badge:"badge-drift"},{name:"Track",fa:"fas fa-flag-checkered",desc:"Purpose-built circuit and time attack cars",color:"#6366f1",badge:"badge-track"},{name:"Race",fa:"fas fa-trophy",desc:"Full race builds and competition cars",color:"#dc2626",badge:"badge-race"},{name:"Drag",fa:"fas fa-tachometer-alt",desc:"Straight-line machines built for the strip",color:"#eab308",badge:"badge-drag"},{name:"Collector",fa:"fas fa-crown",desc:"Rare, investment-grade automobiles",color:"#f59e0b",badge:"badge-collector"}];function catCfg(a){return CATS.find(e=>e.name===a)||{color:"#555",badge:"badge-default",fa:"fas fa-car"}}const AV_COLORS={A:"#3b82f6",B:"#8b5cf6",C:"#ec4899",D:"#f59e0b",E:"#10b981",F:"#6366f1",G:"#14b8a6",H:"#e8392a",I:"#f0a030",J:"#22c55e",K:"#e8392a",L:"#a855f7",M:"#3b82f6",N:"#f59e0b",O:"#10b981",P:"#ec4899",Q:"#14b8a6",R:"#f0a030",S:"#6366f1",T:"#22c55e",U:"#8b5cf6",V:"#e8392a",W:"#3b82f6",X:"#a855f7",Y:"#14b8a6",Z:"#f0a030"};function avColor(a){return AV_COLORS[(a||"?")[0].toUpperCase()]||"#e8392a"}const PH_BG=["#1a0f0f","#0d1714","#0f0f1a","#1a1208","#0d1a16"];function phBg(a){return PH_BG[a.charCodeAt(a.length-1)%PH_BG.length]}const SEED_POSTS=[],SEED_USERS=[],SEED_EVENTS=[],SEED_TIMELINES={},AWARDS_DEF=[{id:"founders",icon:"fas fa-crown",label:"Founders",desc:"Awarded to the original founders of DriveLog.",color:"#fff",bg:"#b45309",border:"#92400e"},{id:"viral",icon:"fas fa-bolt",label:"Viral",desc:"Awarded for a build or post that went truly viral.",color:"#fff",bg:"#1d4ed8",border:"#1e3a8a"},{id:"honorary",icon:"fas fa-medal",label:"Honorary",desc:"Awarded at the discretion of the DriveLog founders.",color:"#fff",bg:"#7e22ce",border:"#581c87"}];function getAwardDef(a){return AWARDS_DEF.find(e=>e.id===a)}
